function esc(value) {
  return String(value === null || value === undefined ? "" : value)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}
function money(value, currency) {
  try { return new Intl.NumberFormat("en-US", { style: "currency", currency: currency || "USD", maximumFractionDigits: 0 }).format(value || 0); }
  catch (e) { return (currency || "USD") + " " + Math.round(value || 0); }
}
const f = $json;
return [{ json: { leadId: f.leadId, error: f.error, text: "⚠️ <b>AI analysis failed · " + esc(f.reference) + "</b>\n" + esc(f.error) + "\nThe lead is back in the dashboard — use Regenerate to retry." } }];
